export const getRealRequestUrl = (c: any): string => {
    const edgeOneHost = c.req.header('eo-pages-host');
    const forwardedHost = c.req.header('x-forwarded-host');
    const hostHeader = c.req.header('host');

    const requestUrl = new URL(c.req.url);

    const forwardedProto = c.req.header('x-forwarded-proto');

    if (edgeOneHost) {
        requestUrl.hostname = edgeOneHost.split(',')[0].trim();
    } else if (forwardedHost) {
        requestUrl.hostname = forwardedHost.split(',')[0].trim();
    } else if (hostHeader) {
        requestUrl.hostname = hostHeader.split(',')[0].trim();
    }

    if (forwardedProto) {
        requestUrl.protocol = forwardedProto.split(',')[0].trim() + ':';
    } else if (requestUrl.hostname !== 'localhost' && requestUrl.hostname !== '127.0.0.1') {
        requestUrl.protocol = 'https:';
    }

    return requestUrl.toString();
};

/**
 * 辅助：校验并正规化单个 IP 字符串
 * 去除空白、端口号及 IPv4 映射的 ::ffff: 前缀
 */
const cleanAndNormalizeIp = (rawIp: string | undefined | null): string | null => {
    if (!rawIp || typeof rawIp !== 'string') return null;
    let ip = rawIp.trim();
    if (!ip || ip.toLowerCase() === 'unknown' || ip.toLowerCase() === 'null') return null;

    // 剥离 IPv4-in-IPv6 映射前缀 (例如 ::ffff:192.0.2.1 -> 192.0.2.1)
    ip = ip.replace(/^::ffff:/i, '');

    // 处理方括号包裹的 IPv6 带端口 (例如 [2001:db8::1]:8080 -> 2001:db8::1)
    if (ip.startsWith('[')) {
        const match = ip.match(/^\[([a-fA-F0-9:]+)\](?::\d+)?$/);
        if (match && match[1]) {
            ip = match[1];
        }
    } else if (ip.includes('.') && ip.includes(':')) {
        // 处理常规 IPv4 带端口 (例如 203.0.113.19:54321 -> 203.0.113.19)
        ip = ip.split(':')[0].trim();
    }

    return isValidIpString(ip) ? ip : null;
};

/**
 * 辅助：验证字符串是否为合法的 IPv4 或 IPv6 基础格式
 */
const isValidIpString = (ip: string): boolean => {
    // IPv4 简略正则
    const ipv4Regex = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
    if (ipv4Regex.test(ip)) return true;
    // IPv6 简略正则（排除非法字符，且至少含有一个冒号）
    const ipv6Regex = /^[a-fA-F0-9:]+$/;
    return ip.includes(':') && ipv6Regex.test(ip) && ip.length <= 45;
};

/**
 * 辅助：判断是否为公网 IP（排除私有内网/本地环回等地址，防止内网转发与未知地址解析失败）
 */
const isPublicIpAddress = (ip: string): boolean => {
    if (ip === '127.0.0.1' || ip === '::1' || ip.startsWith('0.')) return false;
    // 排除私有 A/B/C 类与链路本地 IP
    if (/^10\./.test(ip)) return false;
    if (/^192\.168\./.test(ip)) return false;
    if (/^172\.(?:1[6-9]|2\d|3[0-1])\./.test(ip)) return false;
    if (/^169\.254\./.test(ip)) return false;
    if (/^fc00:/i.test(ip) || /^fe80:/i.test(ip)) return false;
    return true;
};

export const getClientIp = (c: any): string => {
    // 1. 优先提取各大平台及 CDN 权威的单对端真实 IP 请求头（全覆盖 Fastly/Deno/CF/EdgeOne/ESA/阿里云）
    const authoritativeHeaders = [
        'cf-connecting-ip',        // Cloudflare
        'fastly-client-ip',        // Fastly CDN & Deno Deploy 边缘架构
        'eo-connecting-ip',        // 腾讯云 EdgeOne
        'true-client-ip',          // Cloudflare Enterprise / Akamai / 阿里云边缘
        'ali-cdn-real-ip',         // 阿里云 CDN
        'x-aliyun-esa-client-ip',  // 阿里云 ESA
        'esa-client-ip',           // 阿里云 ESA 备用
        'x-deno-client-ip',        // Deno Deploy 扩展
        'x-wasmer-client-ip',      // Wasmer Edge 扩展
        'wasmer-client-ip',        // Wasmer Edge 备用
        'x-spin-client-ip',        // Fermyon Spin Wasm 平台扩展
        'spin-client-ip',          // Fermyon Spin Wasm 平台备用
        'x-client-ip',             // AWS / Apache 常代
        'x-real-ip'                // Nginx / 通用反向代理
    ];

    for (const headerName of authoritativeHeaders) {
        const val = c.req?.header ? c.req.header(headerName) : undefined;
        if (val) {
            const cleaned = cleanAndNormalizeIp(val);
            if (cleaned) return cleaned;
        }
    }

    // 2. 解析 X-Forwarded-For：过滤内网转发及非法占位符，优先提取首个合法公网 IP
    const forwardedFor = c.req?.header ? c.req.header('x-forwarded-for') : undefined;
    if (forwardedFor && typeof forwardedFor === 'string') {
        const parsedIps = forwardedFor
            .split(',')
            .map(part => cleanAndNormalizeIp(part))
            .filter((ip): ip is string => ip !== null);

        // 优先寻找第一个公网真实 IP
        const publicIp = parsedIps.find(ip => isPublicIpAddress(ip));
        if (publicIp) return publicIp;

        // 如果全为内网/本地调试 IP，则降级返回第一个有效合法 IP
        if (parsedIps.length > 0) return parsedIps[0];
    }

    // 3. 兜底尝试从 Hono / Deno / Node 运行时的对端 Socket 连接或 env 上下文中提取
    if (c.env) {
        const envIpCandidate = c.env.REMOTE_ADDR || c.env.remoteAddr || c.env.clientIp || c.env.CF_CONNECTING_IP;
        const cleanedEnvIp = cleanAndNormalizeIp(typeof envIpCandidate === 'object' ? envIpCandidate.hostname || JSON.stringify(envIpCandidate) : envIpCandidate);
        if (cleanedEnvIp) return cleanedEnvIp;
    }

    try {
        const connRemote = c.req?.raw?.connInfo?.remote?.address || c.req?.raw?.remoteAddr;
        const cleanedConn = cleanAndNormalizeIp(typeof connRemote === 'object' ? connRemote.hostname || JSON.stringify(connRemote) : connRemote);
        if (cleanedConn && typeof cleanedConn === 'string') return cleanedConn;
    } catch {}

    return 'unknown';
};
