import { EnvBindings } from '@/app/config';
import { BaseLarkFeishuProvider } from '@/features/auth/providers/baseLarkFeishuProvider';

export class FeishuProvider extends BaseLarkFeishuProvider {
    readonly id = 'feishu';
    readonly name = 'Feishu';
    readonly color = '#3370FF';
    readonly icon = 'iconFeishu';

    protected readonly apiDomain = 'open.feishu.cn';
    protected readonly accountDomain = 'passport.feishu.cn';

    constructor(env: EnvBindings) {
        super(env);
    }

    protected getClientId() {
        return this.env.OAUTH_FEISHU_CLIENT_ID;
    }

    protected getClientSecret() {
        return this.env.OAUTH_FEISHU_CLIENT_SECRET;
    }

    protected getRedirectUri() {
        return this.env.OAUTH_FEISHU_REDIRECT_URI;
    }
}
