import { logger } from '@/shared/utils/logger';
import Database from 'better-sqlite3';
import { drizzle as drizzleSqlite } from 'drizzle-orm/better-sqlite3';
import { drizzle as drizzleMysql } from 'drizzle-orm/mysql2';
import { drizzle as drizzlePg } from 'drizzle-orm/node-postgres';
import { drizzle as drizzleProxy } from 'drizzle-orm/sqlite-proxy';
import { SqliteExecutor } from '@/shared/db/sqliteExecutor';
import { MySqlExecutor } from '@/shared/db/mySqlExecutor';
import { PgExecutor } from '@/shared/db/pgExecutor';
import { D1HttpExecutor } from '@/shared/db/d1HttpExecutor';
import { DbExecutor } from '@/shared/db/executor';
import { createClient } from '@libsql/client/web';
import { drizzle as drizzleLibsql } from 'drizzle-orm/libsql/web';
import { LibsqlExecutor } from '@/shared/db/libsqlExecutor';
import * as sqliteSchema from '@/shared/db/schema/sqlite';
import * as mysqlSchema from '@/shared/db/schema/mysql';
import * as pgSchema from '@/shared/db/schema/pg';

export interface DbConnection {
    executor: DbExecutor;
    db: any; // Drizzle instance
    schema: any;
}

import fs from 'fs';
import path from 'path';

export class DbFactory {
    static async create(): Promise<DbConnection> {
        // Fix for Wasmer or other platforms where DB_USER might be mistakenly named DB_USERNAME
        if (!process.env.DB_USER && process.env.DB_USERNAME) {
            process.env.DB_USER = process.env.DB_USERNAME;
        }

        const dbUrl = process.env.DB_URL || process.env.DATABASE_URL;
        const dbToken = process.env.DB_TOKEN;

        if (dbUrl) {
            try {
                const parsed = new URL(dbUrl);
                
                if (!process.env.DB_ENGINE) {
                    const proto = parsed.protocol.replace(':', '');
                    if (proto === 'postgres' || proto === 'postgresql') process.env.DB_ENGINE = 'postgres';
                    else if (proto === 'mysql') process.env.DB_ENGINE = 'mysql';
                    else if (proto === 'libsql') process.env.DB_ENGINE = 'libsql';
                }
                
                process.env.DB_HOST = process.env.DB_HOST || parsed.hostname;
                process.env.DB_PORT = process.env.DB_PORT || parsed.port;
                process.env.DB_USER = process.env.DB_USER || process.env.DB_USERNAME || decodeURIComponent(parsed.username);
                process.env.DB_PASSWORD = process.env.DB_PASSWORD || decodeURIComponent(parsed.password);
                
                const dbName = parsed.pathname.replace(/^\//, '');
                if (dbName) {
                    process.env.DB_NAME = process.env.DB_NAME || dbName;
                } else {
                    if (process.env.DB_ENGINE === 'postgres') {
                        process.env.DB_NAME = process.env.DB_NAME || 'postgres';
                    }
                }
                
                if (process.env.DB_SSL === undefined) {
                    const sslParam = parsed.searchParams.get('ssl') || parsed.searchParams.get('sslmode');
                    const isDomain = (host: string, domain: string) => host === domain || host.endsWith('.' + domain);
                    const isCloudDb = isDomain(parsed.hostname, 'tidbcloud.com') || 
                                      isDomain(parsed.hostname, 'neon.tech') || 
                                      isDomain(parsed.hostname, 'supabase.co') ||
                                      isDomain(parsed.hostname, 'db.prisma.io');
                    if (isCloudDb || sslParam === 'true' || sslParam === 'require' || sslParam === 'verify-full') {
                        process.env.DB_SSL = 'true';
                    }
                }
            } catch (e) {
                logger.error(`[Database] Failed to parse DATABASE_URL:`, e);
            }
        }

        const engine = (process.env.DB_ENGINE || 'sqlite').toLowerCase();
        const baseDir = process.cwd();

        switch (engine) {
            // ... (mysql/postgres 保持不变)
            case 'mysql': {
                const config = {
                    host: process.env.DB_HOST,
                    port: parseInt(process.env.DB_PORT || '3306', 10),
                    user: process.env.DB_USER,
                    password: process.env.DB_PASSWORD,
                    database: process.env.DB_NAME,
                    ssl: process.env.DB_SSL === 'true'
                };
                const executor = new MySqlExecutor(config);
                const db = drizzleMysql((executor as any).pool, { schema: mysqlSchema, mode: 'default' });
                return { executor, db, schema: mysqlSchema };
            }
            case 'postgres':
            case 'postgresql': {
                const config = { host: process.env.DB_HOST, port: parseInt(process.env.DB_PORT || '5432', 10), user: process.env.DB_USER, password: process.env.DB_PASSWORD, database: process.env.DB_NAME, ssl: process.env.DB_SSL === 'true' };
                const executor = new PgExecutor(config);
                const db = drizzlePg((executor as any).pool, { schema: pgSchema });
                return { executor, db, schema: pgSchema };
            }
            case 'd1':
            case 'cloudflared1': {
                const proxyUrl = dbUrl;
                const proxyToken = dbToken;

                if (!proxyUrl || !proxyToken) {
                    throw new Error('DB_URL (or DATABASE_URL) and DB_TOKEN are required for cloudflared1 engine');
                }

                logger.info(`[Database] Engine: Cloudflare D1 Proxy via ${proxyUrl}`);
                const executor = new D1HttpExecutor(proxyUrl, proxyToken);
                const db = drizzleProxy(executor.getProxyClient(), executor.getBatchProxyClient(), { schema: sqliteSchema });
                return { executor, db, schema: sqliteSchema };
            }
            case 'libsql': {
                if (!dbUrl) {
                    throw new Error('DB_URL (or DATABASE_URL) is required for libsql engine');
                }
                const client = createClient({
                    url: dbUrl,
                    authToken: dbToken || undefined
                });
                const executor = new LibsqlExecutor(client);
                const db = drizzleLibsql(client, { schema: sqliteSchema });
                logger.info(`[Database] Engine: LibSQL via ${dbUrl}`);
                return { executor, db, schema: sqliteSchema };
            }
            case 'sqlite':
            default: {
                const rawPath = (process.env.SQLITE_DB_PATH || './data/nodeauth.db').trim();
                const dbFile = path.isAbsolute(rawPath) ? rawPath : path.resolve(baseDir, rawPath);

                // 审计 1: 打印绝对路径
                logger.info(`[Database] Engine: SQLite. Resolved path: "${dbFile}"`);

                const dbDir = path.dirname(dbFile);
                if (!fs.existsSync(dbDir)) {
                    logger.info(`[Database] Creating missing directory: "${dbDir}"`);
                    fs.mkdirSync(dbDir, { recursive: true });
                }

                // 审计 2: 探测写权限 (由于 Node 和 SQLite 行为差异，需双重验证)
                try {
                    const testFile = path.join(path.dirname(dbFile), '.write_test');
                    fs.writeFileSync(testFile, 'ok');
                    fs.unlinkSync(testFile);
                    logger.info(`[Database] Write Test PASSED for: "${path.dirname(dbFile)}"`);
                } catch (e: any) {
                    logger.error(`[Database] Write Test FAILED: ${e.message}`);
                }

                const sqlite = new Database(dbFile);
                sqlite.pragma('journal_mode = WAL');
                sqlite.pragma('busy_timeout = 10000'); // Scheme 4: Add busy timeout to prevent deadlocks
                const executor = new SqliteExecutor(sqlite);
                const db = drizzleSqlite(sqlite, { schema: sqliteSchema });
                return { executor, db, schema: sqliteSchema };
            }
        }
    }
}
