import { BaseOAuthProvider, OAuthUserInfo } from '@/features/auth/providers/baseOAuthProvider';
import { EnvBindings, AppError } from '@/app/config';

export abstract class BaseLarkFeishuProvider extends BaseOAuthProvider {
    abstract readonly color: string;
    readonly whitelistFields = ['email'];

    protected abstract readonly apiDomain: string; // e.g. open.larksuite.com or open.feishu.cn
    protected abstract readonly accountDomain: string; // e.g. accounts.larksuite.com or passport.feishu.cn

    constructor(env: EnvBindings) {
        super(env);
    }

    protected abstract getClientId(): string | undefined;
    protected abstract getClientSecret(): string | undefined;
    protected abstract getRedirectUri(): string | undefined;

    getAuthorizeUrl(state: string) {
        const clientId = this.getClientId();
        const redirectUri = this.getRedirectUri();

        if (!clientId || !redirectUri) {
            throw new AppError(`oauth_${this.id}_config_missing`, 500);
        }

        const params = new URLSearchParams({
            app_id: clientId,
            redirect_uri: redirectUri,
            state: state
        });

        return { url: `https://${this.accountDomain}/open-apis/authen/v1/authorize?${params.toString()}` };
    }

    private async getAppAccessToken(): Promise<string> {
        const response = await fetch(`https://${this.apiDomain}/open-apis/auth/v3/app_access_token/internal`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json; charset=utf-8'
            },
            body: JSON.stringify({
                app_id: this.getClientId(),
                app_secret: this.getClientSecret()
            })
        });

        if (!response.ok) {
            throw new AppError(`oauth_token_exchange_failed: ${this.name} App Token | ${response.status}`, 502);
        }

        const data: any = await response.json();
        if (data.code !== 0 || !data.app_access_token) {
            throw new AppError(`oauth_token_exchange_failed: ${this.name} App Token | ${data.msg || 'Unknown Error'}`, 400);
        }

        return data.app_access_token;
    }

    async handleCallback(params: string | URLSearchParams, _codeVerifier?: string): Promise<OAuthUserInfo> {
        const code = typeof params === 'string' ? params : params.get('code');

        if (!code) {
            throw new AppError('oauth_code_missing', 400);
        }

        // 1. First get the app_access_token which is required for Lark/Feishu OAuth API
        const appAccessToken = await this.getAppAccessToken();

        // 2. Exchange the authorization code for the user access token and user info
        const tokenResponse = await fetch(`https://${this.apiDomain}/open-apis/authen/v1/access_token`, {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${appAccessToken}`,
                'Content-Type': 'application/json; charset=utf-8'
            },
            body: JSON.stringify({
                grant_type: 'authorization_code',
                code: code
            })
        });

        if (!tokenResponse.ok) {
            throw new AppError(`oauth_token_exchange_failed: ${this.name} User Token | ${tokenResponse.status}`, 502);
        }

        const tokenData: any = await tokenResponse.json();

        if (tokenData.code !== 0 || !tokenData.data) {
            throw new AppError(`oauth_token_exchange_failed: ${this.name} User Token | ${tokenData.msg || 'Unknown Error'}`, 400);
        }

        const userInfo = tokenData.data;

        // Lark/Feishu directly returns user profile fields in the access_token response in v1!
        return {
            id: String(userInfo.open_id || userInfo.union_id || userInfo.user_id),
            username: userInfo.en_name || userInfo.name || '',
            email: userInfo.email || userInfo.enterprise_email || '',
            avatar: userInfo.avatar_url || '',
            provider: this.id
        };
    }
}
