import app from '@/app/index'
import { DbFactory } from '@/shared/db/factory'
import { migrateDatabase } from '@/shared/db/migrator'
import { handleScheduledBackup } from '@/features/backup/backupRoutes'

/**
 * NodeAuth 生产级 Netlify 适配器 (Architect V8 - 多 Cookie 修复版)
 * 
 * 1. 核心修复：引入 multiValueHeaders 支持，解决多个 Set-Cookie 相互覆盖导致的登录失效。
 * 2. 数据库自愈：保持连接异常自动清理缓存逻辑。
 * 3. 路径与环境：维持 process.env 合并与路径还原逻辑。
 * 4. 定时任务支持：检测非 HTTP 触发源，执行备份逻辑。
 */

let cachedDb: any = null;

export const handler = async (event: any, context: any) => {
    try {
        // --- 1. 数据库初始化与迁移 (所有触发源通用) ---
        if (!cachedDb) {
            const userAgent = (event.headers['user-agent'] || event.headers['User-Agent'] || '').toLowerCase();
            const isCronEvent = event.headers['x-nf-event'] === 'schedule';
            
            // 判定是否为 CRON 环境：没有 httpMethod，或者明确是系统调度事件，或者 User-Agent 匹配
            const isCronMode = !event.httpMethod || isCronEvent || userAgent.includes('netlify-cron');
            
            console.log('📡 [DB] Initializing connection for:', isCronMode ? 'CRON' : `HTTP (${event.httpMethod})`);
            
            const engine = String(process.env.DB_ENGINE || 'sqlite').toLowerCase();
            if (engine === 'sqlite') {
                throw new Error('Local SQLite is not supported on Netlify Functions because /tmp storage is ephemeral. Please configure DB_ENGINE and DB_URL for a remote database.');
            }

            const { db, executor } = await DbFactory.create();
            cachedDb = { db, executor };

            if (db && typeof db.on === 'function') {
                db.on('error', (err: any) => {
                    console.error('📡 [DB Pool] Background Error:', err.message);
                    cachedDb = null;
                });
            }

            try {
                await migrateDatabase(executor);
            } catch (err: any) {
                console.error('🗄️ [DB Migrate] Failed:', err.message);
                cachedDb = null;
                return {
                    statusCode: 503,
                    body: JSON.stringify({ success: false, error: 'Database Initialization Failed', detail: err.message })
                };
            }
        }

        // --- 2. 定时任务处理 (Netlify 专用逻辑) ---
        if (process.env.NETLIFY_MODE === 'cron') {
            const userAgent = (event.headers['user-agent'] || event.headers['User-Agent'] || '').toLowerCase();
            
            // 安全加固：识别系统级特征，防止外部恶意触发
            let hasNextRun = false;
            try {
                if (event.body) {
                    const body = JSON.parse(event.isBase64Encoded ? Buffer.from(event.body, 'base64').toString() : event.body);
                    hasNextRun = !!body.next_run;
                }
            } catch (e) {}

            const isSystemTrigger = 
                event.headers['x-nf-event'] === 'schedule' || 
                userAgent.includes('netlify-cron') ||
                hasNextRun;

            // 拦截：如果存在 httpMethod (如外部 curl) 且不具备系统触发特征，则视为恶意触发
            if (event.httpMethod && !isSystemTrigger) {
                console.warn(`⚠️ [Cron] Blocked unauthorized HTTP attempt. UA: ${userAgent}`);
                return {
                    statusCode: 403,
                    body: JSON.stringify({ success: false, error: 'Forbidden: External trigger not allowed' })
                };
            }

            console.log('⏰ [Cron] System scheduled trigger verified.');
            await handleScheduledBackup({ ...process.env, DB: cachedDb.db } as any);
            return {
                statusCode: 200,
                body: JSON.stringify({ success: true, message: 'Scheduled task executed' })
            };
        }

        // 如果构建模式为 api，且由于某种原因收到了定时任务触发 (虽不应发生)，则直接拒绝
        // 这里移除对 User-Agent 的依赖，防止伪造身份攻击
        if (process.env.NETLIFY_MODE === 'api' && !event.httpMethod) {
            return {
                statusCode: 403,
                body: JSON.stringify({ success: false, error: 'Forbidden' })
            };
        }

        // --- 3. 构造标准 Request ---
        const host = event.headers.host || event.headers['Host'] || 'localhost';
        const protocol = event.headers['x-forwarded-proto'] || 'https';

        let path = event.headers['x-nf-original-path'] || event.path || '/';
        if (path.startsWith('/.netlify/functions/api')) {
            path = path.replace('/.netlify/functions/api', '/api');
        }

        const query = event.queryStringParameters ? '?' + new URLSearchParams(event.queryStringParameters).toString() : '';
        const url = `${protocol}://${host}${path}${query}`;

        const request = new Request(url, {
            method: event.httpMethod || 'GET',
            headers: event.headers,
            body: event.body ? (event.isBase64Encoded ? Buffer.from(event.body, 'base64') : event.body) : undefined
        });

        // --- 4. 执行 Hono 逻辑 ---
        const res = await app.fetch(request, {
            ...process.env,
            ...context,
            DB: cachedDb?.db
        }, {
            waitUntil: (promise: Promise<any>) => {
                promise.catch(err => console.error('⚠️ [Netlify Background] Task Error:', err));
            },
            passThroughOnException: () => {}
        } as any);

        // --- 5. 构造响应结果 (关键：分离单值与多值 Header) ---
        const headers: Record<string, string> = {};
        const multiValueHeaders: Record<string, string[]> = {};

        res.headers.forEach((value, key) => {
            if (key.toLowerCase() === 'set-cookie') {
                if (!multiValueHeaders['set-cookie']) multiValueHeaders['set-cookie'] = [];
                multiValueHeaders['set-cookie'].push(value);
            } else {
                headers[key] = value;
            }
        });

        const contentType = res.headers.get('content-type') || '';
        let body;
        if (contentType.includes('application/json')) {
            const text = await res.text();
            try {
                body = JSON.stringify(JSON.parse(text));
            } catch {
                body = text;
            }
        } else {
            body = await res.text();
        }

        return {
            statusCode: res.status,
            headers,
            multiValueHeaders,
            body: body
        };

    } catch (err: any) {
        console.error('🛑 [Architect] Runtime Crash:', err);
        const errorMsg = err.message || '';
        if (errorMsg.includes('terminated') || errorMsg.includes('timeout') || errorMsg.includes('Connection')) {
            cachedDb = null;
        }
        return {
            statusCode: 500,
            body: JSON.stringify({ success: false, error: 'Internal Server Error', detail: err.message })
        };
    }
}
