import { EnvBindings } from '@/app/config';
import { BaseLarkFeishuProvider } from '@/features/auth/providers/baseLarkFeishuProvider';

export class LarkProvider extends BaseLarkFeishuProvider {
    readonly id = 'lark';
    readonly name = 'Lark';
    readonly color = '#00D6D9';
    readonly icon = 'iconLark';

    protected readonly apiDomain = 'open.larksuite.com';
    protected readonly accountDomain = 'accounts.larksuite.com';

    constructor(env: EnvBindings) {
        super(env);
    }

    protected getClientId() {
        return this.env.OAUTH_LARK_CLIENT_ID;
    }

    protected getClientSecret() {
        return this.env.OAUTH_LARK_CLIENT_SECRET;
    }

    protected getRedirectUri() {
        return this.env.OAUTH_LARK_REDIRECT_URI;
    }
}
