import { BaseOAuthProvider, OAuthUserInfo } from '@/features/auth/providers/baseOAuthProvider';
import { EnvBindings, AppError } from '@/app/config';

// Helper to base64url encode an ArrayBuffer or Uint8Array
function base64UrlEncode(buffer: ArrayBuffer | Uint8Array): string {
    let binary = '';
    const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
    for (let i = 0; i < bytes.byteLength; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary)
        .replace(/\+/g, '-')
        .replace(/\//g, '_')
        .replace(/=/g, '');
}

// Generate random code verifier
function generateCodeVerifier(): string {
    const array = new Uint8Array(32);
    crypto.getRandomValues(array);
    return base64UrlEncode(array);
}

// Generate code challenge (S256) from verifier
async function generateCodeChallenge(verifier: string): Promise<string> {
    const encoder = new TextEncoder();
    const data = encoder.encode(verifier);
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    return base64UrlEncode(hashBuffer);
}

export class TwitterProvider extends BaseOAuthProvider {
    readonly id = 'twitter';
    readonly name = 'X (Twitter)';
    readonly color = '#000000';
    readonly icon = 'iconTwitter';
    readonly whitelistFields = ['id']; // Twitter API v2 通常不提供 email，只能通过 twitter:数字ID 作为白名单凭据

    constructor(env: EnvBindings) {
        super(env);
    }

    async getAuthorizeUrl(state: string) {
        const clientId = this.env.OAUTH_TWITTER_CLIENT_ID;
        const redirectUri = this.env.OAUTH_TWITTER_REDIRECT_URI;

        if (!clientId || !redirectUri) {
            throw new AppError('oauth_twitter_config_missing', 500);
        }

        const codeVerifier = generateCodeVerifier();
        const codeChallenge = await generateCodeChallenge(codeVerifier);

        const params = new URLSearchParams({
            response_type: 'code',
            client_id: clientId,
            redirect_uri: redirectUri,
            state: state,
            scope: 'tweet.read users.read offline.access',
            code_challenge: codeChallenge,
            code_challenge_method: 'S256'
        });

        return {
            url: `https://twitter.com/i/oauth2/authorize?${params.toString()}`,
            codeVerifier: codeVerifier
        };
    }

    async handleCallback(params: string | URLSearchParams, codeVerifier?: string): Promise<OAuthUserInfo> {
        const code = typeof params === 'string' ? params : params.get('code');

        if (!code) {
            throw new AppError('oauth_code_missing', 400);
        }
        if (!codeVerifier) {
            throw new AppError('oauth_code_verifier_missing', 400); // PKCE strict requirement for Twitter
        }

        const clientId = this.env.OAUTH_TWITTER_CLIENT_ID as string;
        const clientSecret = this.env.OAUTH_TWITTER_CLIENT_SECRET as string;
        const redirectUri = this.env.OAUTH_TWITTER_REDIRECT_URI as string;

        // 1. Exchange Code for Access Token
        const basicAuth = btoa(`${clientId}:${clientSecret}`);
        const tokenResponse = await fetch('https://api.twitter.com/2/oauth2/token', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
                'Authorization': `Basic ${basicAuth}`
            },
            body: new URLSearchParams({
                code: code,
                grant_type: 'authorization_code',
                client_id: clientId,
                redirect_uri: redirectUri,
                code_verifier: codeVerifier
            })
        });

        if (!tokenResponse.ok) {
            let errorDesc = '';
            try {
                const err = await tokenResponse.json() as any;
                errorDesc = err.error_description || err.error;
            } catch (e) {
                errorDesc = 'Unknown error';
            }
            throw new AppError(`oauth_token_exchange_failed: Twitter | ${tokenResponse.status} - ${errorDesc}`, 502);
        }

        const tokenData: any = await tokenResponse.json();
        const accessToken = tokenData.access_token;

        // 2. Fetch User Profile
        const userResponse = await fetch('https://api.twitter.com/2/users/me?user.fields=profile_image_url', {
            headers: {
                'Authorization': `Bearer ${accessToken}`
            }
        });

        if (!userResponse.ok) {
            throw new AppError(`oauth_api_error: Twitter | ${userResponse.status}`, 502);
        }

        const userDataRes: any = await userResponse.json();
        const userData = userDataRes.data;

        if (!userData || !userData.id) {
            throw new AppError('oauth_api_error: Twitter | Missing user data', 502);
        }

        // Twitter usually doesn't return email in v2 API without special permission.
        return {
            id: String(userData.id),
            username: userData.username, // Twitter handle, e.g., "nodeauth"
            email: '', 
            avatar: userData.profile_image_url || '',
            provider: this.id
        };
    }
}
