import { Context, Next } from 'hono';
import { getCookie, setCookie } from 'hono/cookie';
import { AppError, EnvBindings } from '@/app/config';
import { verifySecureJWT, generateSecureJWT } from '@/shared/utils/crypto';
import { SessionService } from '@/features/auth/sessionService';

export async function authMiddleware(c: Context<{ Bindings: EnvBindings, Variables: { user: any, sessionId: string } }>, next: Next) {
    // 1. 获取 JWT (优先从 Authorization Header 获取 Bearer Token)
    const authHeader = c.req.header('Authorization');
    let token = '';
    let isBearer = false;

    if (authHeader && authHeader.startsWith('Bearer ')) {
        token = authHeader.slice(7);
        isBearer = true;
    } else {
        token = getCookie(c, 'auth_token') || '';
    }

    if (!token) {
        throw new AppError('no_session', 401);
    }

    // 2. CSRF 校验 (仅针对 Cookie 认证，Bearer 认证依靠 CORS 机制防范 CSRF)
    if (!isBearer) {
        const csrfCookie = getCookie(c, 'csrf_token');
        const csrfHeader = c.req.header('X-CSRF-Token');
        if (!csrfCookie || !csrfHeader || csrfCookie !== csrfHeader) {
            throw new AppError('csrf_mismatch', 403);
        }
    }

    // 3. 验证 JWT
    const payload = await verifySecureJWT(token, c.env.JWT_SECRET);

    if (!payload || !payload.userInfo) {
        throw new AppError('token_expired', 401);
    }

    // 4. 从 DB 校验设备会话有效性 (防幽灵 JWT 攻击/被踢出)
    const sessionId = payload.sessionId;

    // 如果存在配置允许老的无 session 令牌，可做降级处理。在这里采用严格安全策略，一律要求有 Session
    if (!sessionId) {
        throw new AppError('session_invalid_schema', 401);
    }

    const sessionService = new SessionService(c.env);
    const userAgent = c.req.header('User-Agent');
    const isValid = await sessionService.validateSession(sessionId, userAgent);
    if (!isValid) {
        // 如果数据库里 session 已被删除，代表被挤下线或过期，强行拦截
        throw new AppError('session_kicked_out', 401);
    }

    // 5. Sliding window expiration (滑动过期续签，仅针对 Cookie 认证)
    if (!isBearer && payload.exp) {
        const now = Math.floor(Date.now() / 1000);
        // 如果剩余有效期不足 3 天，则刷新 Token
        if (payload.exp - now < 3 * 24 * 60 * 60) {
            const newToken = await generateSecureJWT({
                sessionId: payload.sessionId,
                userInfo: payload.userInfo
            }, c.env.JWT_SECRET, 7 * 24 * 60 * 60);

            const isSecure = c.env.ENVIRONMENT !== 'development';

            // 续签 auth_token 7 天
            setCookie(c, 'auth_token', newToken, {
                httpOnly: true,
                secure: isSecure,
                sameSite: 'Lax',
                maxAge: 7 * 24 * 60 * 60,
                path: '/',
            });

            // 同步顺延 csrf_token 的时间
            const csrfCookie = getCookie(c, 'csrf_token');
            if (csrfCookie) {
                setCookie(c, 'csrf_token', csrfCookie, {
                    httpOnly: false,
                    secure: isSecure,
                    sameSite: 'Lax',
                    maxAge: 7 * 24 * 60 * 60,
                    path: '/',
                });
            }
        }
    }

    // 验证通过，将用户信息挂载到上下文，供后续路由使用
    c.set('user', payload.userInfo);
    c.set('sessionId', sessionId);
    await next();
}
