import { DbExecutor, DbEngine } from '@/shared/db/executor';

export class D1HttpExecutor implements DbExecutor {
    readonly engine: DbEngine = 'cloudflared1';

    constructor(private proxyUrl: string, private proxyToken: string) {}

    private async sendRequest(body: any) {
        const response = await fetch(this.proxyUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${this.proxyToken}`
            },
            body: JSON.stringify(body)
        });
        if (!response.ok) {
            throw new Error(`D1 Proxy Error: ${await response.text()}`);
        }
        return await response.json();
    }

    async exec(sql: string): Promise<void> {
        await this.sendRequest({ sql, method: 'run' });
    }

    prepare(sql: string) {
        return {
            get: async (...params: any[]) => {
                const res = await this.sendRequest({ sql, params, method: 'get' }) as any;
                return res.rows && res.rows.length > 0 ? res.rows[0] : undefined;
            },
            run: async (...params: any[]) => {
                await this.sendRequest({ sql, params, method: 'run' });
            }
        };
    }

    async batch(sqls: string[]): Promise<void> {
        if (sqls.length === 0) return;
        const batchPayload = sqls.map(sql => ({ sql, params: [] }));
        await this.sendRequest({ batch: batchPayload });
    }

    getProxyClient() {
        return async (sql: string, params: any[], method: 'run' | 'all' | 'values' | 'get') => {
            const data = await this.sendRequest({ sql, params, method }) as any;
            return { rows: data.rows || [] };
        };
    }

    getBatchProxyClient() {
        return async (queries: { sql: string, params: any[], method: 'run' | 'all' | 'values' | 'get' }[]) => {
            const data = await this.sendRequest({ batch: queries }) as any;
            return data.results.map((r: any) => ({ rows: r.results || [] }));
        };
    }
}
