import { DbExecutor, DbEngine } from '@/shared/db/executor';
import type { Client } from '@libsql/client/web';

export class LibsqlExecutor implements DbExecutor {
    readonly engine: DbEngine = 'libsql';

    constructor(private client: Client) { }

    async exec(sql: string): Promise<void> {
        await this.client.executeMultiple(sql);
    }

    prepare(sql: string) {
        return {
            get: async (...params: any[]) => {
                const rs = await this.client.execute({ sql, args: params });
                return rs.rows[0] || undefined;
            },
            run: async (...params: any[]) => {
                const rs = await this.client.execute({ sql, args: params });
                return {
                    changes: rs.rowsAffected,
                    lastInsertRowid: rs.lastInsertRowid
                };
            }
        };
    }

    async batch(sqls: string[]): Promise<void> {
        await this.client.batch(sqls, 'write');
    }
}
